namespace Sace.Api.Tests;

public class CrossValidationExtractionCorrectionTests {
  public static IEnumerable<object[]> ExtractionCases(){
    yield return ["COMMERCIAL_INVOICE","Invoice No: INV-100\nDate: 2026-11-04\nDescription: EMPAQUES DE CAUCHO\nQuantity: 6500 PIEZAS\nTotal: 4358.25 USD\nIncoterm: FOB",new[]{DocumentFieldCodes.InvoiceNumber,DocumentFieldCodes.Date,DocumentFieldCodes.Description,DocumentFieldCodes.Quantity,DocumentFieldCodes.Unit,DocumentFieldCodes.TotalAmount,DocumentFieldCodes.Currency,DocumentFieldCodes.Incoterm}];
    yield return ["COVE_ACK","Reference: INV-100\nDescription: EMPAQUES DE CAUCHO\nQuantity: 6500 PZA\nTotal: USD 4358.25",new[]{DocumentFieldCodes.InvoiceNumber,DocumentFieldCodes.Description,DocumentFieldCodes.Quantity,DocumentFieldCodes.Unit,DocumentFieldCodes.TotalAmount,DocumentFieldCodes.Currency}];
    yield return ["PACKING_LIST","Description: EMPAQUES DE CAUCHO\nCantidad: 6500 PZA\nPeso bruto: 126.8 KG\nBultos: 10",new[]{DocumentFieldCodes.Description,DocumentFieldCodes.Quantity,DocumentFieldCodes.Unit,DocumentFieldCodes.GrossWeight,DocumentFieldCodes.PackageCount}];
    yield return ["TRANSPORT_DOCUMENT","Gross weight: 126.8 KG\nPackages: 10\nB/L: BL-9001",new[]{DocumentFieldCodes.GrossWeight,DocumentFieldCodes.PackageCount,DocumentFieldCodes.TransportReference}];
    yield return ["PEDIMENTO","Cantidad: 6500 PZA\nPeso bruto: 126.8 KG",new[]{DocumentFieldCodes.Quantity,DocumentFieldCodes.Unit,DocumentFieldCodes.GrossWeight}];
  }

  [Theory]
  [MemberData(nameof(ExtractionCases))]
  public async Task Supported_document_text_produces_expected_fields_with_traceability(string type,string text,string[] expected){await using var f=await ExtractionFixture.Create();var doc=await f.AddDocument(type,text);var count=await f.Extractor.ExtractDocumentAsync(doc.Id,f.User.Id);var fields=await f.Db.DocumentFields.Where(x=>x.OperationDocumentId==doc.Id&&x.ExtractionMethod==ExtractionMethod.PDF_TEXT).ToListAsync();Assert.True(count>=expected.Length);foreach(var code in expected){var field=Assert.Single(fields,x=>x.FieldCode==code);Assert.False(string.IsNullOrWhiteSpace(field.RawValue));Assert.False(string.IsNullOrWhiteSpace(field.NormalizedValue));Assert.NotNull(field.Confidence);Assert.Contains("PDF text",field.SourceLocator);}Assert.Equal("TEXT_EXTRACTED",(await f.Db.OperationDocuments.FindAsync(doc.Id))!.TextExtractionStatus);}

  [Fact]
  public async Task Existing_metadata_mapping_is_explicit_and_never_swaps_quantity_and_weight(){await using var f=await ExtractionFixture.Create();f.Operation.Quantity=6500;f.Operation.Unit="PZA";f.Operation.GrossWeight=126.8m;f.Operation.GoodsDescription="EMPAQUES DE CAUCHO";f.Operation.CommercialValue=4358.25m;f.Operation.Currency="USD";var doc=await f.AddDocument("PEDIMENTO","Pedimento con capa de texto sin los campos comparables");await f.Db.SaveChangesAsync();await f.Extractor.ExtractDocumentAsync(doc.Id,f.User.Id);var fields=await f.Db.DocumentFields.Where(x=>x.OperationDocumentId==doc.Id&&x.ExtractionMethod==ExtractionMethod.EXISTING_METADATA).ToDictionaryAsync(x=>x.FieldCode);Assert.Equal("6500",fields[DocumentFieldCodes.Quantity].NormalizedValue);Assert.Equal("TradeOperation.Quantity",fields[DocumentFieldCodes.Quantity].SourceLocator);Assert.Equal("PZA",fields[DocumentFieldCodes.Unit].NormalizedValue);Assert.Equal("TradeOperation.Unit",fields[DocumentFieldCodes.Unit].SourceLocator);Assert.Equal("126.8",fields[DocumentFieldCodes.GrossWeight].NormalizedValue);Assert.Equal("TradeOperation.GrossWeight",fields[DocumentFieldCodes.GrossWeight].SourceLocator);Assert.Equal("EMPAQUES DE CAUCHO",fields[DocumentFieldCodes.Description].NormalizedValue);Assert.Equal("4358.25",fields[DocumentFieldCodes.CommercialValue].NormalizedValue);Assert.Equal("USD",fields[DocumentFieldCodes.Currency].NormalizedValue);Assert.NotEqual(fields[DocumentFieldCodes.Quantity].NormalizedValue,fields[DocumentFieldCodes.GrossWeight].NormalizedValue);}

  [Fact]
  public async Task Extracted_pedimento_field_has_priority_over_existing_metadata(){await using var f=await ExtractionFixture.Create();f.Operation.Quantity=6500;var invoice=await f.AddDocument("COMMERCIAL_INVOICE","Quantity: 6400 PZA");var pedimento=await f.AddDocument("PEDIMENTO","Quantity: 6400 PZA");await f.AddRule("PRIORITY",DocumentFieldCodes.Quantity,"COMMERCIAL_INVOICE",DocumentFieldCodes.Quantity,"PEDIMENTO",CrossComparisonType.EXACT_NUMERIC);await f.Db.SaveChangesAsync();var result=Assert.Single(await f.Engine.ExecuteAsync(f.Operation.Id,null,f.User.Id));Assert.Equal(CrossValidationOutcome.MATCH,result.Outcome);Assert.Equal("6400",result.TargetNormalizedValue);Assert.Equal(ExtractionMethod.PDF_TEXT,result.TargetExtractionMethod);Assert.NotEqual(ExtractionMethod.EXISTING_METADATA,result.TargetExtractionMethod);}

  [Fact]
  public async Task Synthetic_documents_reextract_idempotently_and_all_expected_crosses_match(){await using var f=await ExtractionFixture.Create();await f.AddDocument("COMMERCIAL_INVOICE","Invoice: INV-100\nDescription: EMPAQUES DE CAUCHO\nQuantity: 6500 PZA\nTotal: 4358.25 USD");await f.AddDocument("PEDIMENTO","Quantity: 6500 PZA\nGross weight: 126.8 KG");await f.AddDocument("COVE_ACK","Invoice: INV-100\nDescription: EMPAQUES DE CAUCHO\nQuantity: 6500 PZA\nTotal: 4358.25 USD");await f.AddDocument("PACKING_LIST","Description: EMPAQUES DE CAUCHO\nQuantity: 6500 PZA\nGross weight: 126.8 KG\nPackages: 10");await f.AddDocument("TRANSPORT_DOCUMENT","Gross weight: 126.8 KG\nPackages: 10\nB/L: BL-9001");
    await f.AddRule("INV-COVE-QTY",DocumentFieldCodes.Quantity,"COMMERCIAL_INVOICE",DocumentFieldCodes.Quantity,"COVE_ACK",CrossComparisonType.EXACT_NUMERIC);await f.AddRule("INV-COVE-UNIT",DocumentFieldCodes.Unit,"COMMERCIAL_INVOICE",DocumentFieldCodes.Unit,"COVE_ACK",CrossComparisonType.NORMALIZED_IDENTIFIER);await f.AddRule("INV-COVE-VALUE",DocumentFieldCodes.TotalAmount,"COMMERCIAL_INVOICE",DocumentFieldCodes.TotalAmount,"COVE_ACK",CrossComparisonType.CURRENCY_AMOUNT);await f.AddRule("INV-PED-QTY",DocumentFieldCodes.Quantity,"COMMERCIAL_INVOICE",DocumentFieldCodes.Quantity,"PEDIMENTO",CrossComparisonType.EXACT_NUMERIC);await f.AddRule("INV-PED-UNIT",DocumentFieldCodes.Unit,"COMMERCIAL_INVOICE",DocumentFieldCodes.Unit,"PEDIMENTO",CrossComparisonType.NORMALIZED_IDENTIFIER);await f.AddRule("PL-PED-QTY",DocumentFieldCodes.Quantity,"PACKING_LIST",DocumentFieldCodes.Quantity,"PEDIMENTO",CrossComparisonType.EXACT_NUMERIC);await f.AddRule("PL-PED-WEIGHT",DocumentFieldCodes.GrossWeight,"PACKING_LIST",DocumentFieldCodes.GrossWeight,"PEDIMENTO",CrossComparisonType.EXACT_NUMERIC);await f.AddRule("PL-TR-WEIGHT",DocumentFieldCodes.GrossWeight,"PACKING_LIST",DocumentFieldCodes.GrossWeight,"TRANSPORT_DOCUMENT",CrossComparisonType.EXACT_NUMERIC);await f.AddRule("PL-TR-PACKAGES",DocumentFieldCodes.PackageCount,"PACKING_LIST",DocumentFieldCodes.PackageCount,"TRANSPORT_DOCUMENT",CrossComparisonType.EXACT_NUMERIC);
    var first=await f.Extractor.ReextractOperationAsync(f.Operation.Id,f.User.Id);var firstCount=await f.Db.DocumentFields.CountAsync();var second=await f.Extractor.ReextractOperationAsync(f.Operation.Id,f.User.Id);var secondCount=await f.Db.DocumentFields.CountAsync();Assert.Equal(5,first.DocumentsProcessed);Assert.Equal(5,first.DocumentsWithText);Assert.Equal(0,first.DocumentsWithoutText);Assert.Empty(first.Warnings);Assert.Equal(first.FieldsExtracted,second.FieldsExtracted);Assert.Equal(firstCount,secondCount);var results=await f.Engine.ExecuteAsync(f.Operation.Id,null,f.User.Id);Assert.Equal(9,results.Count);Assert.All(results,x=>Assert.Equal(CrossValidationOutcome.MATCH,x.Outcome));Assert.All(results,x=>Assert.False(string.IsNullOrWhiteSpace(x.SourceRawValue)));Assert.All(results,x=>Assert.False(string.IsNullOrWhiteSpace(x.TargetRawValue)));}

  [Fact]
  public async Task Quantity_difference_is_mismatch_with_exact_difference(){await using var f=await ExtractionFixture.Create();await f.AddDocument("COMMERCIAL_INVOICE","Quantity: 6500 PZA");await f.AddDocument("PEDIMENTO","Quantity: 6400 PZA");await f.AddRule("NEGATIVE-QTY",DocumentFieldCodes.Quantity,"COMMERCIAL_INVOICE",DocumentFieldCodes.Quantity,"PEDIMENTO",CrossComparisonType.EXACT_NUMERIC);var result=Assert.Single(await f.Engine.ExecuteAsync(f.Operation.Id,null,f.User.Id));Assert.Equal(CrossValidationOutcome.MISMATCH,result.Outcome);Assert.Equal(100m,result.NumericDifference);Assert.NotEqual(CrossValidationOutcome.INSUFFICIENT_EVIDENCE,result.Outcome);}

  [Fact]
  public async Task Pdf_without_text_fabricates_nothing_and_remains_insufficient(){await using var f=await ExtractionFixture.Create();var invoice=await f.AddDocument("COMMERCIAL_INVOICE","");await f.AddDocument("PEDIMENTO","Quantity: 6500 PZA");await f.AddRule("NO-TEXT",DocumentFieldCodes.Quantity,"COMMERCIAL_INVOICE",DocumentFieldCodes.Quantity,"PEDIMENTO",CrossComparisonType.EXACT_NUMERIC);var summary=await f.Extractor.ReextractOperationAsync(f.Operation.Id,f.User.Id);Assert.Equal(1,summary.DocumentsWithoutText);Assert.Contains(summary.Warnings,x=>x.Contains("sin texto extraíble"));Assert.Empty(await f.Db.DocumentFields.Where(x=>x.OperationDocumentId==invoice.Id).ToListAsync());var result=Assert.Single(await f.Engine.ExecuteAsync(f.Operation.Id,null,f.User.Id));Assert.Equal(CrossValidationOutcome.INSUFFICIENT_EVIDENCE,result.Outcome);Assert.Contains("Documento sin texto extraíble",result.Explanation);}

  [Fact]
  public async Task PdfPig_extracts_text_from_valid_synthetic_pdf(){await using var stream=new MemoryStream(ValidTextPdf("Quantity: 6500 PZA"));var text=await new PdfPigTextExtractor().ExtractAsync(stream,default);Assert.Contains("Quantity",text);Assert.Contains("6500",text);Assert.Contains("PZA",text);}

  [Fact]
  public async Task Reextract_endpoint_returns_detailed_summary_and_diagnostic_shape(){using var factory=new SaceFactory();var client=factory.CreateClient();var login=await client.PostAsJsonAsync("/api/auth/login",new{email="admin@sace.local",password="Admin123!"});using var loginJson=JsonDocument.Parse(await login.Content.ReadAsStringAsync());client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",loginJson.RootElement.GetProperty("token").GetString());var operations=await client.GetFromJsonAsync<JsonElement>("/api/operations?search=IMP-2026-000001&page=1&pageSize=10");var id=operations.GetProperty("items")[0].GetProperty("id").GetGuid();var response=await client.PostAsync($"/api/operations/{id}/document-fields/reextract",null);response.EnsureSuccessStatusCode();using var summary=JsonDocument.Parse(await response.Content.ReadAsStringAsync());Assert.True(summary.RootElement.TryGetProperty("documentsProcessed",out _));Assert.True(summary.RootElement.TryGetProperty("documentsWithText",out _));Assert.True(summary.RootElement.TryGetProperty("fieldsExtracted",out _));Assert.True(summary.RootElement.TryGetProperty("documentsWithoutText",out _));Assert.True(summary.RootElement.GetProperty("warnings").ValueKind==JsonValueKind.Array);var diagnostic=await client.GetFromJsonAsync<JsonElement>($"/api/operations/{id}/document-fields");Assert.Equal(JsonValueKind.Array,diagnostic.GetProperty("documents").ValueKind);}

  sealed class ExtractionFixture(SqliteConnection connection,SaceDbContext db,User user,TradeOperation operation,DictionaryStorage storage):IAsyncDisposable {
    public SaceDbContext Db=>db;public User User=>user;public TradeOperation Operation=>operation;public DocumentFieldExtractor Extractor{get;}=new(db,storage,new StreamTextExtractor(),new FieldNormalizationService());public CrossValidationEngine Engine{get;}=new(db,new DocumentFieldExtractor(db,storage,new StreamTextExtractor(),new FieldNormalizationService()));
    public static async Task<ExtractionFixture>Create(){var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Extraction",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var operation=new TradeOperation{Folio=$"X-{Guid.NewGuid():N}",PedimentoNumber="26 48 9999 6000001",Period="2026-11",OperationDate=new(2026,11,4,0,0,0,DateTimeKind.Utc),TariffFraction="40169304",Quantity=6500,Unit="PZA",GrossWeight=126.8m,GoodsDescription="EMPAQUES DE CAUCHO",CommercialValue=4358.25m,Currency="USD"};db.AddRange(user,operation);await db.SaveChangesAsync();return new(connection,db,user,operation,new());}
    public async Task<OperationDocument>AddDocument(string code,string text){var type=await db.DocumentTypes.SingleOrDefaultAsync(x=>x.Code==code);if(type is null){type=new DocumentType{Code=code,Name=code};db.DocumentTypes.Add(type);}var path=$"{code}-{Guid.NewGuid():N}.pdf";storage.Files[path]=text;var doc=new OperationDocument{TradeOperation=operation,DocumentType=type,OriginalFileName=path,StoredFileName=path,FilePath=path,Extension=".pdf",MimeType="application/pdf",FileSize=Encoding.UTF8.GetByteCount(text),UploadedBy=user.Id,ValidationStatus=ValidationStatus.Valid};db.OperationDocuments.Add(doc);await db.SaveChangesAsync();return doc;}
    public async Task AddRule(string code,string sourceField,string sourceType,string targetField,string targetType,CrossComparisonType comparison){db.CrossValidationRules.Add(new(){Code=code,Version=1,Name=code,Category="Correction",SourceDocumentTypeCode=sourceType,SourceFieldCode=sourceField,TargetDocumentTypeCode=targetType,TargetFieldCode=targetField,ComparisonType=comparison,MissingEvidenceBehavior=MissingEvidenceBehavior.INSUFFICIENT_EVIDENCE,IsActive=true});await db.SaveChangesAsync();}
    public async ValueTask DisposeAsync(){await db.DisposeAsync();await connection.DisposeAsync();}
  }
  sealed class DictionaryStorage:IFileStorageService { public Dictionary<string,string> Files{get;}=[];public Task<(string storedName,string relativePath)>SaveAsync(Guid operationId,string documentCode,IFormFile file,CancellationToken ct)=>throw new NotSupportedException();public Task<Stream?>OpenAsync(string relativePath,CancellationToken ct)=>Task.FromResult<Stream?>(Files.TryGetValue(relativePath,out var text)?new MemoryStream(Encoding.UTF8.GetBytes(text)):null);}
  sealed class StreamTextExtractor:IPdfTextExtractor { public async Task<string>ExtractAsync(Stream stream,CancellationToken ct){using var reader=new StreamReader(stream,Encoding.UTF8,leaveOpen:true);return await reader.ReadToEndAsync(ct);}}

  private static byte[] ValidTextPdf(string value){
    var objects=new[]{
      "<< /Type /Catalog /Pages 2 0 R >>",
      "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
      "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
      "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
      $"<< /Length {Encoding.ASCII.GetByteCount($"BT /F1 12 Tf 72 720 Td ({value}) Tj ET")} >>\nstream\nBT /F1 12 Tf 72 720 Td ({value}) Tj ET\nendstream"
    };
    var pdf=new StringBuilder("%PDF-1.4\n");var offsets=new List<int>{0};for(var i=0;i<objects.Length;i++){offsets.Add(Encoding.ASCII.GetByteCount(pdf.ToString()));pdf.Append($"{i+1} 0 obj\n{objects[i]}\nendobj\n");}var xref=Encoding.ASCII.GetByteCount(pdf.ToString());pdf.Append($"xref\n0 {objects.Length+1}\n0000000000 65535 f \n");foreach(var offset in offsets.Skip(1))pdf.Append($"{offset:0000000000} 00000 n \n");pdf.Append($"trailer\n<< /Size {objects.Length+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF");return Encoding.ASCII.GetBytes(pdf.ToString());
  }
}
